export const EMOJI = {"🍖":"food","🌾":"food","🪵":"wood","🪨":"stone","🪙":"gold","💰":"gold","👥":"pop","🧍":"person","❤":"heart","⚔":"attack","🎯":"range","👟":"speed","👁":"sight","💪":"morale","⛽":"fuel","★":"star","⭐":"star","⚠":"warn","☠":"skull","🏗":"build","🤖":"bot","☰":"menu","✕":"close","✖":"close","🔊":"sound","🔇":"mute","💤":"idle","🕊":"dove","🏳":"flag","🚩":"outpost","⏸":"pause","▶":"play","💾":"save","📂":"load","📜":"scroll","⬆":"up","◀":"back","➕":"plus","✚":"med","🛠":"tools","🗑":"trash","✋":"stop","🔬":"research","⛔":"ban","🚫":"ban","✉":"mail","✍":"pen","🎁":"gift","⚖":"scale","🤝":"handshake","🤫":"lock","👑":"crown","🎖":"medal","🌱":"spring","☀":"summer","🍂":"autumn","❄":"winter","☄":"meteor","☢":"nuclear","🏛":"wonder","💥":"explosion","🎆":"rocketlauncher","⛰":"mountain","🌲":"forest","🌿":"forest","➖":"f_line","⏬":"f_column","🔺":"f_wedge","⬛":"f_square","⁘":"f_loose","👷":"worker","🪓":"axe","🗡":"sword","🔱":"spear","🏹":"bow","🔫":"rifle","🪖":"soldier","🐎":"cavalry","🏇":"cavalry","🐴":"stable","🛡":"celo","🚜":"tank","🛞":"catapult","🧨":"cannon","💣":"cannon","🚀":"rocket","🕵":"spy","🚂":"train","🚆":"train","🚃":"armtrain","🛶":"fishboat","⛵":"sailship","🚤":"fishboat","⛴":"transport","🚢":"warship","🐋":"sub","🤿":"sub","🛩":"scout","✈":"fighter","🛬":"bomber","🚁":"heli","🪂":"para","🛰":"abm","🐘":"elephant","🐏":"catapult","😡":"axe","🪶":"bow","🏰":"town","🏠":"house","📦":"storage","🛣":"road","🌉":"bridge","🛤":"rail","🚉":"station","⚓":"dock","🛫":"airfield","🗼":"tower","⚙":"workshop","🧱":"wall","🏚":"bunker","🏡":"celohouse","🪦":"memorial","⛏":"worker","◆":""};
// SVG-Markup eines Symbols (übernimmt die Textfarbe)
export function icon(name, cls = '') {
  const d = ICONS[name]; if (!d) return '';
  return '<svg class="ic' + (cls ? ' ' + cls : '') + '" viewBox="0 0 ' + d[0] + ' ' + d[1] + '" aria-hidden="true"' + (d[2] ? ' fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"' : ' fill="currentColor"') + '>' + d[3].replace(/fill="#000"/g, 'fill="currentColor"') + '</svg>';
}
// Ersetzt Emojis in HTML-Text durch Symbole und entfernt die übrigen
const RE = /(?:\p{Extended_Pictographic}|[◆☰✕✖★✚⚔⏸▶◀⁘➖⬛⏬])\uFE0F?/gu;
export function iconize(html) { return String(html).replace(RE, m => { const n = EMOJI[m.replace('\uFE0F', '')]; return n ? icon(n) : ''; }); }
